/**
 * Abbreviation units, smallest first. `digits` is the number of integer digits
 * at which the unit starts (1000 has four digits, 1,00,000 has six, ...).
 */
export const ABBREVIATION_UNITS = [
    { digits: 1, places: 0, en: "", short: "", hi: "" },
    { digits: 4, places: 3, en: "thousand", short: "K", hi: "हज़ार" },
    { digits: 6, places: 5, en: "lakh", short: "L", hi: "लाख" },
    { digits: 8, places: 7, en: "crore", short: "Cr", hi: "करोड़" },
    { digits: 10, places: 9, en: "arab", short: "Ar", hi: "अरब" },
    { digits: 12, places: 11, en: "kharab", short: "Kh", hi: "खरब" },
];

/**
 * Suffixes accepted by `parse()`, lower-cased, mapped to a power of ten.
 * Powers (rather than multipliers) keep the maths exact: the decimal point is
 * shifted on the digit string instead of multiplying a float.
 */
export const PARSE_SUFFIXES = {
    k: 3,
    thousand: 3,
    thousands: 3,
    hazaar: 3,
    hazar: 3,
    "हज़ार": 3,
    "हजार": 3,
    l: 5,
    lac: 5,
    lacs: 5,
    lakh: 5,
    lakhs: 5,
    "लाख": 5,
    cr: 7,
    crore: 7,
    crores: 7,
    "करोड़": 7,
    "करोड": 7,
    ar: 9,
    arab: 9,
    arabs: 9,
    "अरब": 9,
    kh: 11,
    kharab: 11,
    "खरब": 11,
};

export const DEVANAGARI_DIGITS = "०१२३४५६७८९";
export const LATIN_DIGITS = "0123456789";

export const LOCALES = ["en", "hi"];

export function assertLocale(locale) {
    if (!LOCALES.includes(locale)) {
        throw new TypeError(`indian-number: unsupported locale ${JSON.stringify(locale)}, expected "en" or "hi"`);
    }
    return locale;
}
